  bottomN: 'In the bottom N',
  aboveMean: 'Above average',
  belowMean: 'Below average',
  aboveMedian: 'Above the median',
  belowMedian: 'Below the median',
  zAbove: 'Standard deviations above the mean',
  zBelow: 'Standard deviations below the mean',
  outlier: 'An outlier',
