    n: sorted.length,
    min: sorted[0],
    max: sorted[sorted.length - 1],
    mean,
    stddev: sorted.length > 1 ? Math.sqrt(m2 / (sorted.length - 1)) : 0,
    median: quantileOf(sorted, 0.5),
    q1,
    q3,
    iqr: q3 - q1,
