  if (a.install !== b.install || a.uninstall !== b.uninstall) return false;
  if ((a.version || '') !== (b.version || '')) return false;
  return sameSet(capabilitiesOf(a), capabilitiesOf(b))
    && sameSet(regionsOf(a), regionsOf(b));
