    if (part.length > 1 && part.charCodeAt(0) === 48) return null;
    const octet = Number(part);
    if (octet > 255) return null;
    // Multiplication rather than `<< 8`: the running value passes 2^31 on the
    // last octet, and a shift would hand back a negative number.
