/** A currency symbol → code table for the common cases parsing tolerates. */
const SYMBOL_CODES = Object.freeze({
  $: 'USD', '€': 'EUR', '£': 'GBP', '¥': 'JPY', '₹': 'INR',
  '₩': 'KRW', '₽': 'RUB', '₺': 'TRY', '₴': 'UAH', '₪': 'ILS',
});

/** Symbols to render for the common codes; falls back to the code itself. */
const CODE_SYMBOLS = Object.freeze({
  USD: '$', EUR: '€', GBP: '£', JPY: '¥', INR: '₹',
  KRW: '₩', RUB: '₽', TRY: '₺', UAH: '₴', ILS: '₪',
});

/** Leading number, tolerant of a sign, separators and a decimal mark. */
const NUMBER_BODY = /[+-]?[\d\s.,  ]*\d/;

/**
 * Parse a locale-written number out of a fragment.
 * @param {string} text the text
 * @param {string} [locale] the locale
 * @returns {number|null} the number
 */
