  hex8: createRadixType(RADIX_PRESETS.hex8),
  hex16: createRadixType(RADIX_PRESETS.hex16),
  hex32: createRadixType(RADIX_PRESETS.hex32),
  binary: createRadixType(RADIX_PRESETS.binary),
  binary8: createRadixType(RADIX_PRESETS.binary8),
  octal: createRadixType(RADIX_PRESETS.octal),

  // Unit-aware numbers, stored in the named base unit.
  bytes: createUnitType({ system: 'data', unit: 'B', display: 'auto' }),
  megabytes: createUnitType({ system: 'data', unit: 'MB' }),
  gigabytes: createUnitType({ system: 'data', unit: 'GB' }),
  bitrate: createUnitType({ system: 'bitrate', unit: 'Mbps' }),
  gigabits: createUnitType({ system: 'bitrate', unit: 'Gbps' }),

