/*
 * Spreading several catalogues into one object makes shadowing silent: a name
 * declared twice keeps the last one, and the shipped type it replaced simply
 * stops existing. That is how a `duration` unit type would have quietly taken
 * the temporal one's name. Checked at load, once, so it can only ever be a
 * development-time mistake.
 */
{
  const seen = new Set();
  for (const source of [
    TEMPORAL_TYPES, NETWORK_TYPES, STRUCTURED_TYPES, AGGREGABLE_TYPES,
    ENGINEERING_TYPES, SI_TYPES, TEMPERATURE_TYPES, CURRENCY_TYPES,
  ]) {
    for (const name of Object.keys(source)) {
      if (seen.has(name)) throw new Error(`[lattice] data type "${name}" is declared twice`);
      seen.add(name);
    }
  }
}

















