    this.#filtered = null;
    this.#latest.set(key, value);
    this.#counts.set(key, (this.#counts.get(key) || 0) + 1);
    this.#stamps.set(key, this.#now());

    const readings = this.#history.get(key) || [];
    readings.push(value);
