  sum: { pushable: true, class: 'identical', sql: 'sum(%c)' },
  avg: { pushable: true, class: 'identical', sql: 'avg(%c)' },
  min: { pushable: true, class: 'identical', sql: 'min(%c)' },
  max: { pushable: true, class: 'identical', sql: 'max(%c)' },
