    // ticked — or partial once any row has been taken out of it.
    if (this.#predicate) return this.#predicate.except.size ? 'partial' : true;
    // The display array's identity is stable while nothing changed: the source
    // returns the same lazy view until a stage rebuilds it. Caching the scan on
    // that identity plus the selection version makes this O(1) on an idle
    // re-read, which is the scroll path (BACKLOG-0001349).
    const display = this.#rows.display();
    if (display === this.#headerCache.display && this.#version === this.#headerCache.version) {
      return this.#headerCache.state;
    }
