  /** @type {Map<string, CellRecord[]>} */
  #free = new Map();
  /** @type {(columnId: string, kind: string) => object} */
  #create;
  /** @type {(record: CellRecord) => void} */
  #reset;
  /** @type {number} */
  #bucketMax;
  /** @type {number} */
  #allocations = 0;
  /** @type {number} */
  #reuses = 0;
  /** @type {number} */
  #live = 0;

  /**
   * @param {object} opts
   * @param {(columnId: string, kind: string) => object} opts.create builds a fresh cell element
   * @param {(record: CellRecord) => void} [opts.reset] hook run when a cell is released
   * @param {number} [opts.bucketMax] free nodes kept per bucket
   */
