    this.doc = ctx.document;
    this.root = el(this.doc, 'div', { class: `${CLS.statusBar}__panel`, attrs: { 'data-align': ctx.align || 'end' } });
    if (ctx.label) this.root.appendChild(el(this.doc, 'span', { class: `${CLS.statusBar}__label`, text: ctx.label }));
