  title: 'lat-views__title',
  count: 'lat-views__count',
  list: 'lat-views__list',
  empty: 'lat-views__empty',
  item: 'lat-views__item',
  itemActive: 'lat-views__item--active',
  itemEditing: 'lat-views__item--editing',
  apply: 'lat-views__apply',
  name: 'lat-views__name',
  description: 'lat-views__description',
  badges: 'lat-views__badges',
  badge: 'lat-views__badge',
  badgeDefault: 'lat-views__badge--default',
  badgeShared: 'lat-views__badge--shared',
  badgePrivate: 'lat-views__badge--private',
