  /** @type {HTMLElement|null} */ root = null;
  /** @type {Array<() => void>} */ off = [];
  /** @type {ViewPickerHost} */ host = {};
  /** @type {Record<string, unknown>} */ props = {};
  /** @type {string|null} the view whose name is being edited in place */ editing = null;
  /** @type {string|null} the view whose delete is awaiting confirmation */ confirming = null;
  /** @type {string} the text in the save-as box, kept across repaints */ draft = '';

  /**
   * Format a message from the grid's catalogue.
   *
   * The same accessor the tool panels have. This control takes a host adapter
   * rather than a grid, so the messages are handed in beside it; the fallback
   * is what keeps a control built in a test rendering English rather than raw
   * catalogue keys.
   *
   * @param {string} key a catalogue key
   * @param {Record<string, unknown>} [params] parameters
   * @returns {string} the formatted message
   */
