    const input = /** @type {any} */ (el(this.doc, 'input', {
      class: VIEW_CLS.input,
      attrs: { type: 'text', placeholder: this.t('views.namePlaceholder'), 'aria-label': this.t('views.nameLabel') },
    }));
    input.value = this.draft;
