      // Built-in defaults, then the grid's own builder, then the column's own
      // declaration — each handed the previous result as its `defaults`, and
      // the more specific level winning on suppression (§18.5).
      const items = resolveMenuChain(defaults, [
        { layer: this.#cellMenu === false ? false : this.#items, where: 'contextMenu' },
        { layer: this.#columnLayer(params.column), where: `column '${params.colId}' contextMenu` },
      ], params);
