  /** @type {object} the grid */
  #grid;

  /** @type {object} the owning document */
  #doc;

  /** @type {object} the DOM renderer */
  #renderer;

  /** @type {object} the module registry, for host-supplied editors */
  #registry;

  /** @type {object|null} the cell layer, so a released cell repaints properly */
  #cellLayer;

  /** @type {object|null} the live editor */
